#![allow(unused_imports)]
use verus::prelude::*;

verus! {

    /// Given three mutable vectors `a`, `b`, and `sum`, and an integer `N`,
    /// set every element of `b` to the constant value `N + 2`.
    ///
    /// Requirements:
    ///  - 0 < N < 1000
    ///  - a.len() == N
    ///  - b.len() == N
    ///  - sum.len() == 1
    ///
    /// Postcondition:
    ///  - For all k in 0..N, b[k] == N + 2
    ///  - `a` and `sum` are unchanged.
    pub fn myfun(a: &mut Vec<i32>, b: &mut Vec<i32>, sum: &mut Vec<i32>, N: i32)
        requires
            0 < N,
            N < 1000,
            a.len() == N as usize,
            b.len() == N as usize,
            sum.len() == 1,
        ensures
            // Every element of b has been set to N + 2
            forall |k: usize| k < N as usize ==> b[k] == N + 2,
        ensures
            // a is unchanged
            forall |k: usize| k < a.len() ==> a[k] == old(a)[k],
        ensures
            // sum is unchanged
            forall |k: usize| k < sum.len() ==> sum[k] == old(sum)[k],
    {
        let n: usize = N as usize;
        let mut i: usize = 0;
        // Loop to set each b[i] = N + 2
        while i < n
            invariant
                // loop index is always in range
                i <= n,
                // for all indices < i, we have already set b[k] == N + 2
                forall |k: usize| k < i ==> b[k] == N + 2,
            decreases n - i
        {
            b[i] = N + 2;
            i += 1;
        }
        // At exit, i == n, so by the invariant, for all k < n, b[k] == N + 2,
        // which matches our postcondition.
    }
}